#!/usr/bin/env Rscript
suppressMessages({library(data.table);library(xts);library(PerformanceAnalytics);library(tidyverse);library(ggthemes);library(viridis);library(ggrepel);library(patchwork)})
source("/mnt/ssd1/stockviz/R2/backtests/common/runtime.R");source_common("charts")
ROOT<-"/mnt/ssd1/stockviz/R2/backtests/Trend Filtering and Momentum Signals";V<-file.path(ROOT,"india/vectorized");d<-fread(file.path(V,"daily_returns.csv"));b<-fread(file.path(ROOT,"india/daily_returns.csv"));d[,DATE:=as.Date(DATE)];b[,DATE:=as.Date(as.numeric(DATE),origin="1970-01-01")];b<-b[SYSTEM%in%c("Momentum_FF60","Momentum_FF70")];all<-rbind(d,b,fill=TRUE);systems<-sort(unique(all$SYSTEM));ret<-lapply(systems,function(s)xts(all[SYSTEM==s]$RETURN,order.by=all[SYSTEM==s]$DATE));names(ret)<-systems;win<-list(pre=c(as.Date("1900-01-01"),as.Date("2019-12-31")),post=c(as.Date("2020-05-01"),as.Date("2100-01-01")),full=c(as.Date("1900-01-01"),as.Date("2100-01-01")));for(w in names(win)){x<-lapply(ret,function(z)z[index(z)>=win[[w]][1]&index(z)<=win[[w]][2]]);x<-x[vapply(x,NROW,integer(1))>20];st<-max(vapply(x,function(z)min(index(z)),as.Date("1900-01-01")));x<-lapply(x,function(z)z[index(z)>=st]);plotCumDrawdown(x,title=sprintf("India corrected paper filter vs momentum | %s",toupper(w)),subtitle="Vectorized gross-capped engine; paper FF60/FF70 and matched momentum benchmarks",outPath=file.path(V,sprintf("cum_dd_%s.png",w)),linetypeBySeries=TRUE,exactEnd=TRUE)};cat("Rendered corrected India cumulative/drawdown charts\n")
